from rest_framework.decorators import api_view
from rest_framework.response import Response


@api_view(["POST"])
def create_book(request):
    # می‌تواند از JSON، فرم یا multipart بیاید
    title = request.data.get("title")
    price = request.data.get("price")
    tags = request.data.getlist("tags", [])  # اگر چندمقداری باشد
    return Response({
        "title": title,
        "price": price,
        "tags": tags,
    })

class ProfileView(APIView):
    def get(self, request):
        if request.user.is_authenticated:
            return Response({
                "id": request.user.id,
                "username": request.user.username,
                "email": request.user.email,
                "is_staff": request.user.is_staff,
                "is_superuser": request.user.is_superuser,
            })
        return Response({"detail": "احراز هویت نشده"}, status=401)

class DebugAuthView(APIView):
    def get(self, request):
        return Response({
            "user": str(request.user),
            "auth_type": type(request.auth).__name__,
            "auth_repr": str(request.auth) if request.auth else None,
        })

class ClientInfoView(APIView):
    def get(self, request):
        return Response({
            "user_agent": request.headers.get("User-Agent"),
            "accept": request.headers.get("Accept"),
            "content_type": request.headers.get("Content-Type"),
            "authorization": bool(request.headers.get("Authorization")),
            "x_request_id": request.headers.get("X-Request-ID"),
            "client_ip": self.get_client_ip(request),
        })

    def get_client_ip(self, request):
        # اگر پروکسی دارید، X-Forwarded-For
        x_forwarded = request.headers.get("X-Forwarded-For")
        if x_forwarded:
            return x_forwarded.split(",")[0].strip()
        return request.META.get("REMOTE_ADDR")

@api_view(["GET", "POST", "DELETE"])
def flexible(request):
    if request.method == "GET":
        return Response({"action": "list"})
    if request.method == "POST":
        return Response({"action": "create"}, status=201)
    if request.method == "DELETE":
        return Response(status=204)
    return Response(status=405)

class UploadView(APIView):
    def post(self, request):
        ct = request.content_type
        if ct == "application/json":
            return Response({"format": "json", "data": request.data})
        if ct.startswith("multipart/"):
            return Response({
                "format": "multipart",
                "files": list(request.FILES.keys()),
            })
        if ct == "application/x-www-form-urlencoded":
            return Response({"format": "form", "data": request.data})
        return Response({"detail": "فرمت پشتیبانی نمی‌شود."}, status=415)

class DocumentUploadView(APIView):
    parser_classes = [MultiPartParser, FormParser]

    def post(self, request):
        # هر دو راه کار می‌کند
        file1 = request.FILES.get("document")
        file2 = request.data.get("document")

        if not file1:
            return Response({"detail": "فایل ارسال نشده."}, status=400)

        # بررسی نوع
        if not file1.name.endswith((".pdf", ".docx")):
            return Response({"detail": "فقط PDF و DOCX مجاز است."}, status=400)

        # بررسی اندازه
        if file1.size > 10 * 1024 * 1024:
            return Response({"detail": "حجم فایل بیش از ۱۰ مگابایت."}, status=400)

        return Response({
            "name": file1.name,
            "size": file1.size,
            "content_type": file1.content_type,
        })

